MCQS = [
    (_q("Fuel formed under the earth's surface by the decomposition of organic matter is called ______", 'زمین کے نیچے نامیاتی مادے کے گلنے سے بننے والا ایندھن کہلاتا ہے', 'د ځمکې لاندې د عضوي موادو له وروستېدو جوړ سون توکی بلل کېږي'), ['Organic fuel', 'Biogas', 'Fossil fuel', 'Inorganic fuel'], 2, 'p.158-159.'),
    (_q('Which of the following causes the least pollution when burnt?', 'جلنے پر کون سا سب سے کم آلودگی کرتا ہے؟', 'کوم یو په سوځېدو تر ټولو لږه ککړتیا کوي؟'), ['Petrol', 'Diesel', 'Coal', 'Natural gas'], 3, 'p.162: natural gas is relatively clean-burning.'),
    (_q('Which of these is not a renewable source of energy?', 'ان میں سے کون سا قابلِ تجدید ذریعہ نہیں؟', 'له دې څخه کومه نوې کېدونکې سرچینه نه ده؟'), ['The sun', 'Natural gas', 'Wind', 'Ocean tidal energy'], 1, 'Natural gas is a fossil fuel (p.157).'),
    (_q('A solar cell is made up of', 'سولر سیل کس سے بنتا ہے؟', 'لمریزه حجره له څه جوړه ده؟'), ['Silicon', 'Teflon', 'Titanium', 'Magnesium'], 0, 'Solar cells are made of the semiconductor silicon (not stated in the text).'),
    (_q('A solar cell converts ______', 'سولر سیل بدلتا ہے', 'لمریزه حجره بدلوي'), ['Heat energy into electrical energy', 'Solar energy into electrical energy', 'Heat energy into light energy', 'Solar energy into light energy'], 1, 'p.167.'),
    (_q('The fuel used in the nuclear reactor is ______', 'جوہری ری ایکٹر میں استعمال ہونے والا ایندھن ہے', 'په اټومي ریکټور کې کارېدونکی سون توکی دی'), ['Cadmium', 'Uranium', 'Radium', 'Thorium'], 1, 'p.169: Uranium-235.'),
    (_q('The state of coal with lowest carbon content is ______', 'سب سے کم کاربن والی کوئلے کی حالت ہے', 'تر ټولو لږ کاربن لرونکی د ډبرسکرو حالت دی'), ['Bituminous coal', 'Anthracite coal', 'Lignite', 'None of these'], 2, 'p.160.'),
    (_q('A unit of electricity means', 'بجلی کے ایک یونٹ کا مطلب ہے', 'د برېښنا یو یونټ مانا'), ['Megawatt', 'Nanowatt', 'Kilowatt hour', 'Joule'], 2, 'p.174.'),
    (_q('Which of the following problems is associated with the burning of coal?', 'کوئلہ جلانے سے کون سا مسئلہ وابستہ ہے؟', 'د ډبرسکرو له سوځولو کومه ستونزه تړلې ده؟'), ['Acid rain', 'Carbon dioxide emissions', 'Ash with toxic metal impurities', 'All of these'], 3, 'Burning coal gives SO2 (acid rain), CO2 and ash, so all apply (p.178). The scan underlines (b).'),
    (_q('Solar energy stored in material such as wood, grain, sugar and municipal waste is called ______', 'لکڑی، اناج، چینی اور شہری فضلے میں ذخیرہ شمسی توانائی کہلاتی ہے', 'په لرګیو، غله، بوره او ښاري کثافاتو کې زېرمه لمریزه انرژي بلل کېږي'), ['Fossil fuels', 'Biomass', 'Geothermal energy', 'Natural gas'], 1, 'Biomass (key points p.183).'),
    (_q('The world faces an energy crisis because ______', 'دنیا کو توانائی کے بحران کا سامنا ہے کیونکہ', 'نړۍ د انرژۍ له بحران سره مخ ده ځکه'), ['World demand for energy will increase', 'World oil production will peak and begin to decline', 'Shortages and the resulting escalation of prices can shock the economic and political order', 'All of the above'], 3, 'p.181-182.'),
    (_q('A fuel cell combines hydrogen and ______ to produce electricity, heat and water.', 'فیول سیل ہائیڈروجن اور ___ ملا کر بجلی، حرارت اور پانی بناتا ہے', 'د سون حجره هایډروجن او ___ یوځای کوي او برېښنا، تودوخه او اوبه جوړوي'), ['Carbon', 'Oxygen', 'Uranium', 'Silicon'], 1, 'p.172.'),
    (_q('Fossils are the', 'فوسل ہیں', 'فوسیلونه دي'), ['Dead remains of living organism', 'Coal mines', 'Kind of natural resource', 'Living beings'], 0, 'p.159 fig 5.2.'),
    (_q('Petroleum is mixture of', 'پیٹرولیم کس کا آمیزہ ہے؟', 'پټرولیم د څه ګډوله ده؟'), ['Petrol', 'Diesel', 'Petroleum gas', 'All of these'], 3, 'Crude oil is refined into petrol, diesel and petroleum gas.'),
    (_q('Burning of fossil fuel causes', 'رکازی ایندھن جلانے سے ہوتی ہے', 'د فوسیلي سون توکو سوځول رامنځته کوي'), ['Air pollution', 'Global warming', 'Both (a) & (b)', 'None of these'], 2, 'p.158, p.178.'),
]

SQS = [
    (_q('What would happen if there was no electricity?', 'اگر بجلی نہ ہو تو کیا ہوگا؟', 'که برېښنا نه وي څه به کېږي؟'), 'Lights, fans, appliances, water pumps, communication, hospitals and industries would stop; production and employment would fall and the economy and standard of life would decline (p.175-177).'),
    (_q('What is overuse of electricity?', 'بجلی کا زیادہ استعمال کیا ہے؟', 'د برېښنا ډېره کارونه څه ده؟'), 'Using more electricity than needed, e.g. leaving appliances on when not required or using high-consumption appliances; it wastes limited resources and adds to shortages and pollution (p.182).'),
    (_q('What are the advantages and disadvantages of using petroleum?', 'پیٹرولیم کے استعمال کے فوائد و نقصانات کیا ہیں؟', 'د پټرولیم د کارونې ګټې او زیانونه څه دي؟'), 'Advantages: liquid and easy to use; used for electricity and to make medicines, plastics and other goods; easy energy by direct combustion. Disadvantages: non-renewable and limited; extraction alters the environment; burning causes air pollution and greenhouse gases; Pakistan must import it (p.158, 161, 176).'),
    (_q('Give two examples of ways to conserve energy at home.', 'گھر میں توانائی بچانے کے دو طریقے بتائیں۔', 'په کور کې د انرژۍ ساتلو دوه لارې ووایاست.'), 'Switch off appliances and close gas and water valves when not required; use energy-saving appliances such as tube lights and energy saver bulbs; design homes for sunlight and ventilation (p.182).'),
    (_q('What is a conventional source of energy?', 'روایتی ذریعۂ توانائی کیا ہے؟', 'دودیزه انرژي سرچینه څه ده؟'), 'A fully developed source in established use, e.g. fossil fuels (coal, oil, gas) and nuclear power; they have limited supply and cause pollution (p.158).'),
    (_q('What is the importance of conserving energy?', 'توانائی بچانے کی کیا اہمیت ہے؟', 'د انرژۍ ساتلو اهمیت څه دی؟'), 'Conventional sources are limited and decreasing while population pressure grows; conserving energy makes resources last, reduces cost, shortages and environmental damage (p.181-182).'),
    (_q('What is mmbtu?', 'mmbtu کیا ہے؟', 'mmbtu څه دی؟'), 'MMBTU = one million British thermal units, the unit used to bill natural gas. Since 1 BTU = 1055 J, 1 MMBTU is about 1.055 x 10^9 J (p.175).'),
]

LQS = [
    (_q('Describe various types of fossil fuels.', 'رکازی ایندھن کی اقسام بیان کریں۔', 'د فوسیلي سون توکو ډولونه بیان کړئ.'), 'Coal: from prehistoric plants decomposed without oxygen and compressed; states lignite, bituminous, anthracite (graphite if pressed further); used for electricity. Petroleum (crude oil): liquid from remains of sea animals buried under silt; used for electricity, medicines, plastics. Natural gas: mainly methane CH4, found with petroleum; used for heating, transported by pipelines, relatively clean-burning (p.159-162).'),
    (_q('Write short notes on: a. Coal as fossil fuel b. Petroleum c. Wind as source of energy', 'مختصر نوٹ لکھیں: الف کوئلہ ب پیٹرولیم ج ہوا بطور ذریعہ', 'لنډ یادښتونه ولیکئ: الف ډبرسکاره ب پټرولیم ج باد'), 'a. Coal formed about 300 million years ago from ferns and plants decomposed without oxygen and compressed by sand and dirt; more carbon means cleaner burning; lignite < bituminous < anthracite; Thar coal is a huge reserve. b. Petroleum is liquid crude oil formed from sea animals covered by silt and compressed; drilled with rigs; used for fuel, electricity, medicines, plastics. c. Wind has been used since about 3000 BC for sail boats and later windmills; today wind turbines on 100 ft towers generate electricity; fastest-growing clean source; Pakistan uses it for pumping water and electricity (p.159-164).'),
    (_q('Write in detail the nature and utility of any two non conventional sources of energy.', 'دو غیر روایتی ذرائع کی نوعیت اور افادیت تفصیل سے لکھیں۔', 'د دوو نا دودیزو سرچینو طبیعت او ګټه په تفصیل ولیکئ.'), 'Solar: sunlight converted by solar thermal heating or photovoltaic cells; used in calculators, watches, satellites, solar cookers, geysers, house heating and experimental cars; available everywhere and clean. Wind: moving air turns turbines on tall towers to generate electricity; clean, fastest-growing; used for pumping water and electricity in Pakistan. Both are renewable and clean but limited by weather and cost (p.164-169).'),
    (_q('Compare renewable energy sources with non-renewable sources.', 'قابلِ تجدید اور ناقابلِ تجدید ذرائع کا موازنہ کریں۔', 'نوې او نه نوې کېدونکې سرچینې پرتله کړئ.'), 'Renewable (solar, wind, hydro, biomass, geothermal): virtually inexhaustible, environmentally clean, but limited output and costly to build. Non-renewable (coal, petroleum, natural gas, nuclear fuel): limited and will be used up, easy direct combustion and round-the-clock output, but cause pollution and greenhouse gases (p.157-164).'),
    (_q('Differentiate between conventional energy sources and non-conventional energy sources.', 'روایتی اور غیر روایتی ذرائع میں فرق کریں۔', 'د دودیزو او نا دودیزو سرچینو توپیر وکړئ.'), 'Conventional: fully developed (fossil fuels, nuclear), established technology, round-the-clock output, limited supply, polluting. Non-conventional: renewable (solar, hydropower, wind) still being developed, much smaller environmental impact, still expensive and dependent on conditions like sunny or windy days (p.158).'),
    (_q('Briefly write the process of formation of fossil fuels.', 'رکازی ایندھن بننے کا عمل مختصراً لکھیں۔', 'د فوسیلي سون توکو د جوړېدو بهیر لنډ ولیکئ.'), 'Plants (coal) died in swamps, were covered with water and decomposed without oxygen, losing hydrogen and leaving carbon-rich material that sand and dirt compressed into coal. Sea animals (petroleum) died and were covered by silt on the ocean floor; pressure of the layers compressed them into oil; natural gas forms with petroleum (p.159-162).'),
    (_q('Describe the role of energy in the development of a country.', 'ملک کی ترقی میں توانائی کا کردار بیان کریں۔', 'د هېواد په پرمختګ کې د انرژۍ رول بیان کړئ.'), 'Development is judged by energy consumption; industries need uninterrupted energy, which creates jobs and economic activity and raises living standards; agriculture, health, education and industry all need energy, so access to energy is a prerequisite for sustainable development. Pakistan relies on imported oil and gas, faces severe shortages harming industry and livelihoods, and leaves wind, solar and biomass untapped (p.175-177).'),
    (_q('How critical is hydel power generation for Pakistan? Discuss.', 'پاکستان کے لیے پن بجلی کتنی اہم ہے؟ بحث کریں۔', 'پاکستان ته اوبیزه برېښنا څومره مهمه ده؟ بحث وکړئ.'), 'Hydel is the cheapest source and gives about 30% of generation; Pakistan has huge unexploited potential mainly on the Indus; Tarbela, Mangla and Warsak and Ghazi Barotha (1450 MW) provide electricity and irrigation. Since oil must be imported and shortages are severe, developing hydel power with proper planning is critical (p.165-166, 176-177).'),
    (_q('Nuclear power is regarded as one of the strategies for fulfilling the gaps of power shortages. How has Pakistan been able to use nuclear technology successfully, and what hazards are associated with the use of nuclear energy?', 'جوہری توانائی بجلی کی کمی پوری کرنے کی حکمتِ عملی ہے۔ پاکستان نے اسے کیسے کامیابی سے استعمال کیا اور اس کے کیا خطرات ہیں؟', 'اټومي ځواک د برېښنا کمښت د ډکولو یوه ستراتیژي ده. پاکستان څنګه بریالی کارولی او خطرونه یې څه دي؟'), 'Pakistan runs KANUPP (137 MW, Paradise Point near Karachi) and CHASNUPP-1 (325 MW, near Chashma Barrage, started 1992 with Chinese help); nuclear gives about 3% of generation. Hazards: alpha, beta and gamma radiation penetrates matter, uncontrolled reactions damage whole areas, radiation causes cancer and birth defects; accidents at Three Mile Island, Chernobyl and Fukushima. Remedies: careful operation and waste disposal, cooling, physical barriers and reactor designs that allow for operator error and equipment failure (p.169-181).'),
]
